const pptxgen = require("pptxgenjs");
const fs = require("fs");
const path = require("path");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "2024 JavaScript Rising Stars";

// Color palette: dark navy bg for title/conclusion, light content slides
// Primary: #0F172A (slate-900), Accent: #F59E0B (amber), Secondary: #38BDF8 (sky-400)
// Light bg: #F8FAFC, Card: #FFFFFF, Muted text: #64748B

const C = {
  darkBg:    "0F172A",
  darkBg2:   "1E293B",
  accent:    "F59E0B",
  accentDim: "FCD34D",
  sky:       "38BDF8",
  skyDark:   "0284C7",
  white:     "FFFFFF",
  lightBg:   "F8FAFC",
  cardBg:    "FFFFFF",
  text:      "1E293B",
  textMuted: "64748B",
  textLight: "CBD5E1",
  border:    "E2E8F0",
  star:      "F59E0B",
  barMain:   "38BDF8",
  barHl:     "F59E0B",
};

// Helper: shadow factory (fresh object each call to avoid pptxgenjs mutation bug)
const mkShadow = () => ({ type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.10 });

// ─────────────────────────────────────────────────────────────
// SLIDE 1: Title Cover
// ─────────────────────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.darkBg };

  // Left accent bar
  sl.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 0.18, h: 5.625, fill: { color: C.accent }, line: { color: C.accent } });

  // Subtle grid lines decoration (top right)
  for (let i = 0; i < 5; i++) {
    sl.addShape(pres.shapes.LINE, { x: 7.5 + i * 0.45, y: 0.3, w: 0, h: 1.4, line: { color: "334155", width: 1 } });
  }
  for (let j = 0; j < 4; j++) {
    sl.addShape(pres.shapes.LINE, { x: 7.5, y: 0.3 + j * 0.48, w: 1.8, h: 0, line: { color: "334155", width: 1 } });
  }

  // Stars icon decoration
  sl.addText("★", { x: 7.8, y: 0.15, w: 1.2, h: 0.5, fontSize: 22, color: C.accent, bold: true, align: "center", margin: 0 });

  // Eyebrow
  sl.addText("9TH ANNUAL EDITION  •  BEST OF JS", {
    x: 0.5, y: 1.05, w: 9, h: 0.38,
    fontSize: 11, color: C.accent, bold: true, charSpacing: 3, align: "left", margin: 0
  });

  // Main title
  sl.addText("2024 JavaScript Rising Stars", {
    x: 0.5, y: 1.55, w: 9, h: 1.2,
    fontSize: 44, fontFace: "Arial Black", color: C.white, bold: true, align: "left", margin: 0
  });

  // Subtitle
  sl.addText("The Year's Hottest Projects by GitHub Stars", {
    x: 0.5, y: 2.8, w: 9, h: 0.55,
    fontSize: 22, color: C.sky, align: "left", margin: 0
  });

  // Divider
  sl.addShape(pres.shapes.LINE, { x: 0.5, y: 3.45, w: 8.8, h: 0, line: { color: "334155", width: 1 } });

  // Methodology note
  sl.addText([
    { text: "Methodology: ", options: { bold: true, color: C.accent } },
    { text: "GitHub stars added between Jan 1 – Dec 31, 2024, across projects curated by Best of JS.", options: { color: C.textLight } }
  ], { x: 0.5, y: 3.6, w: 8.8, h: 0.55, fontSize: 13, margin: 0 });

  // Bottom stat pills
  const pills = [
    { label: "Total Projects Tracked", val: "1,000+" },
    { label: "Data Source", val: "GitHub API" },
    { label: "Year", val: "2024" }
  ];
  pills.forEach((p, i) => {
    const px = 0.5 + i * 3.1;
    sl.addShape(pres.shapes.RECTANGLE, { x: px, y: 4.35, w: 2.8, h: 0.85, fill: { color: "1E293B" }, line: { color: "334155", width: 1 } });
    sl.addText(p.val, { x: px, y: 4.42, w: 2.8, h: 0.38, fontSize: 16, fontFace: "Arial Black", color: C.accent, bold: true, align: "center", margin: 0 });
    sl.addText(p.label, { x: px, y: 4.82, w: 2.8, h: 0.28, fontSize: 10, color: C.textLight, align: "center", margin: 0 });
  });
}

// ─────────────────────────────────────────────────────────────
// SLIDE 2: Overall Top 10 — Horizontal bar chart
// ─────────────────────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.lightBg };

  // Header band
  sl.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.78, fill: { color: C.darkBg }, line: { color: C.darkBg } });
  sl.addText("OVERALL TOP 10  —  2024", { x: 0.4, y: 0, w: 7, h: 0.78, fontSize: 13, color: C.accent, bold: true, charSpacing: 3, valign: "middle", margin: 0 });
  sl.addText("★ +38k", { x: 7.8, y: 0, w: 1.8, h: 0.78, fontSize: 13, color: C.accentDim, bold: true, align: "right", valign: "middle", margin: 0 });

  // Slide title
  sl.addText("shadcn/ui Leads Overall with +38k Stars", {
    x: 0.4, y: 0.88, w: 9.2, h: 0.55,
    fontSize: 22, fontFace: "Arial Black", color: C.text, bold: true, margin: 0
  });

  // Horizontal bar chart (BAR with barDir:'bar' = horizontal)
  const top10 = [
    { name: "Payload",      val: 14.4 },
    { name: "Flowise",      val: 14.5 },
    { name: "Supabase",     val: 14.5 },
    { name: "Tauri",        val: 15.9 },
    { name: "htmx",         val: 16.8 },
    { name: "n8n",          val: 17.0 },
    { name: "Bruno",        val: 18.7 },
    { name: "AFFiNE",       val: 19.6 },
    { name: "Excalidraw",   val: 27.0 },
    { name: "shadcn/ui",    val: 38.0 },
  ];

  const colors = top10.map((_, i) => i === 9 ? C.barHl : C.barMain);

  sl.addChart(pres.charts.BAR, [{
    name: "Stars Added (k)",
    labels: top10.map(d => d.name),
    values: top10.map(d => d.val),
  }], {
    x: 0.3, y: 1.52, w: 7.2, h: 3.85,
    barDir: "bar",
    chartColors: colors,
    chartArea: { fill: { color: C.lightBg } },
    catAxisLabelColor: C.text,
    catAxisFontSize: 11,
    valAxisLabelColor: C.textMuted,
    valAxisFontSize: 10,
    valGridLine: { color: C.border, size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelFormatCode: '0.0"k"',
    dataLabelPosition: "outEnd",
    dataLabelColor: C.text,
    dataLabelFontSize: 10,
    showLegend: false,
    valAxisMinVal: 0,
    valAxisMaxVal: 42,
  });

  // Right annotation panel
  sl.addShape(pres.shapes.RECTANGLE, { x: 7.65, y: 1.52, w: 2.1, h: 3.85, fill: { color: C.darkBg }, line: { color: C.darkBg }, shadow: mkShadow() });

  sl.addText("WINNER", { x: 7.65, y: 1.7, w: 2.1, h: 0.32, fontSize: 9, color: C.accent, bold: true, charSpacing: 3, align: "center", margin: 0 });
  sl.addText("shadcn/ui", { x: 7.65, y: 2.0, w: 2.1, h: 0.42, fontSize: 14, fontFace: "Arial Black", color: C.white, bold: true, align: "center", margin: 0 });
  sl.addText("+38.0k", { x: 7.65, y: 2.42, w: 2.1, h: 0.55, fontSize: 26, fontFace: "Arial Black", color: C.barHl, bold: true, align: "center", margin: 0 });
  sl.addShape(pres.shapes.LINE, { x: 7.85, y: 3.1, w: 1.7, h: 0, line: { color: "334155", width: 1 } });
  sl.addText("2nd Year\nIn A Row", { x: 7.65, y: 3.18, w: 2.1, h: 0.55, fontSize: 12, color: C.textLight, align: "center", margin: 0 });
  sl.addShape(pres.shapes.LINE, { x: 7.85, y: 3.84, w: 1.7, h: 0, line: { color: "334155", width: 1 } });
  sl.addText(["Gap to #2\n", "+11k"].join(""), { x: 7.65, y: 3.92, w: 2.1, h: 0.55, fontSize: 11, color: C.textLight, align: "center", margin: 0 });

  // Footer note
  sl.addText("Stars added Jan 1 – Dec 31, 2024  |  Source: risingstars.js.org/2024", {
    x: 0.3, y: 5.3, w: 9.4, h: 0.25, fontSize: 9, color: C.textMuted, align: "left", margin: 0
  });
}

// ─────────────────────────────────────────────────────────────
// SLIDE 3: shadcn/ui Deep Dive
// ─────────────────────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.lightBg };

  // Header band
  sl.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.78, fill: { color: C.darkBg }, line: { color: C.darkBg } });
  sl.addText("SHADCN/UI  —  DEEP DIVE", { x: 0.4, y: 0, w: 9, h: 0.78, fontSize: 13, color: C.accent, bold: true, charSpacing: 3, valign: "middle", margin: 0 });

  sl.addText("Copy-Paste Components Win for the Second Consecutive Year", {
    x: 0.4, y: 0.9, w: 9.2, h: 0.6,
    fontSize: 20, fontFace: "Arial Black", color: C.text, bold: true, margin: 0
  });

  // Left: star chart (column)
  sl.addChart(pres.charts.BAR, [{
    name: "Stars Added",
    labels: ["2023", "2024"],
    values: [39.5, 38.0],
  }], {
    x: 0.3, y: 1.6, w: 3.5, h: 2.6,
    barDir: "col",
    chartColors: [C.sky, C.barHl],
    chartArea: { fill: { color: C.lightBg } },
    catAxisLabelColor: C.text,
    catAxisFontSize: 12,
    valAxisLabelColor: C.textMuted,
    valAxisFontSize: 10,
    valGridLine: { color: C.border, size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelFormatCode: '0.0"k"',
    dataLabelPosition: "outEnd",
    dataLabelColor: C.text,
    dataLabelFontSize: 12,
    showLegend: false,
    valAxisMinVal: 0,
    valAxisMaxVal: 45,
    showTitle: true,
    title: "GitHub Stars Added",
    titleColor: C.textMuted,
    titleFontSize: 11,
