14, fontFace: \"Arial Black\", color: C.text, bold: true, margin: 0 });\n\n  vueNotes.forEach((n, i) => {\n    const ny = 2.05 + i * 1.05;\n    sl.addShape(pres.shapes.RECTANGLE, { x: 6.0, y: ny, w: 3.7, h: 0.92, fill: { color: C.white }, line: { color: \"BBF7D0\", width: 1 }, shadow: mkShadow() });\n    sl.addShape(pres.shapes.RECTANGLE, { x: 6.0, y: ny, w: 0.1, h: 0.92, fill: { color: \"34D399\" }, line: { color: \"34D399\" } });\n    sl.addText(n.title, { x: 6.18, y: ny + 0.07, w: 3.44, h: 0.28, fontSize: 12, bold: true, color: C.text, margin: 0 });\n    sl.addText(n.body, { x: 6.18, y: ny + 0.35, w: 3.44, h: 0.52, fontSize: 10, color: C.textMuted, margin: 0 });\n  });\n\n  sl.addShape(pres.shapes.RECTANGLE, { x: 6.0, y: 5.15, w: 3.7, h: 0.3, fill: { color: \"F0FDF4\" }, line: { color: \"BBF7D0\", width: 1 } });\n  sl.addText(\"shadcn/ui's success inspired shadcn-vue — cross-framework influence\", {\n    x: 6.0, y: 5.15, w: 3.7, h: 0.3, fontSize: 9, color: \"166534\", align: \"center\", valign: \"middle\", margin: 4\n  });\n\n  sl.addText(\"Stars added Jan 1 – Dec 31, 2024  |  Source: risingstars.js.org/2024\", {\n    x: 0.3, y: 5.35, w: 5.9, h: 0.2, fontSize: 9, color: C.textMuted, margin: 0\n  });\n}\n\n// ─────────────────────────────────────────────────────────────\n// SLIDE 7: Emerging Themes\n// ─────────────────────────────────────────────────────────────\n{\n  const sl = pres.addSlide();\n  sl.background = { color: C.lightBg };\n\n  sl.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.78, fill: { color: C.darkBg }, line: { color: C.darkBg } });\n  sl.addText(\"EMERGING THEMES  —  2024\", { x: 0.4, y: 0, w: 9, h: 0.78, fontSize: 13, color: C.accent, bold: true, charSpacing: 3, valign: \"middle\", margin: 0 });\n\n  sl.addText(\"AI Tools, Desktop Apps, and Browser-Based Innovation Shape 2024\", {\n    x: 0.4, y: 0.9, w: 9.2, h: 0.55,\n    fontSize: 20, fontFace: \"Arial Black\", color: C.text, bold: true, margin: 0\n  });\n\n  // 3 theme cards top row + 1 wide card bottom\n  const themes = [\n    {\n      emoji: \"🤖\",\n      label: \"AI-Powered Tools\",\n      color: C.barHl,\n      projects: [\n        \"n8n  +17.0k — workflow automation with native AI\",\n        \"Flowise  +14.5k — visual LLM flow builder\",\n        \"Supabase  +14.5k — open-source backend + AI\",\n        \"AFFiNE  +19.6k — knowledge base with AI\",\n      ]\n    },\n    {\n      emoji: \"🖥\",\n      label: \"Desktop / Mobile Apps\",\n      color: C.sky,\n      projects: [\n        \"Tauri  +15.9k — desktop & mobile apps via web frontend\",\n        \"Lighter than Electron, Rust-powered backend\",\n        \"Cross-platform: Windows, macOS, Linux, iOS, Android\",\n      ]\n    },\n    {\n      emoji: \"🌐\",\n      label: \"Browser Innovation\",\n      color: \"A78BFA\",\n      projects: [\n        \"PGlite — Postgres via WebAssembly in the browser\",\n        \"WebVM — full virtual machine running in browser\",\n        \"WASM pushing compute-heavy workloads client-side\",\n      ]\n    },\n  ];\n\n  themes.forEach((t, i) => {\n    const tx = 0.3 + i * 3.25;\n    sl.addShape(pres.shapes.RECTANGLE, { x: tx, y: 1.58, w: 3.05, h: 3.65, fill: { color: C.white }, line: { color: C.border, width: 1 }, shadow: mkShadow() });\n    sl.addShape(pres.shapes.RECTANGLE, { x: tx, y: 1.58, w: 3.05, h: 0.52, fill: { color: t.color }, line: { color: t.color } });\n    sl.addText(t.emoji + \"  \" + t.label, { x: tx + 0.1, y: 1.6, w: 2.85, h: 0.46, fontSize: 13, fontFace: \"Arial Black\", color: C.darkBg, bold: true, valign: \"middle\", margin: 0 });\n    t.projects.forEach((p, pi) => {\n      sl.addText(\"•  \" + p, { x: tx + 0.12, y: 2.2 + pi * 0.52, w: 2.82, h: 0.45, fontSize: 10, color: C.text, margin: 0 });\n    });\n  });\n\n  // Footer note\n  sl.addText(\"4 of the top 10 overall projects have significant AI capabilities or integrations\", {\n    x: 0.3, y: 5.3, w: 9.4, h: 0.25, fontSize: 10, color: C.textMuted, italic: true, align: \"center\", margin: 0\n  });\n}\n\n// ─────────────────────────────────────────────────────────────\n// SLIDE 8: Takeaways — Dark close\n// ─────────────────────────────────────────────────────────────\n{\n  const sl = pres.addSlide();\n  sl.background = { color: C.darkBg };\n\n  // Right accent bar\n  sl.addShape(pres.shapes.RECTANGLE, { x: 9.82, y: 0, w: 0.18, h: 5.625, fill: { color: C.accent }, line: { color: C.accent } });\n\n  // Subtle grid decoration top left\n  for (let i = 0; i < 5; i++) {\n    sl.addShape(pres.shapes.LINE, { x: 0.3 + i * 0.45, y: 0.3, w: 0, h: 1.2, line: { color: \"334155\", width: 1 } });\n  }\n  for (let j = 0; j < 4; j++) {\n    sl.addShape(pres.shapes.LINE, { x: 0.3, y: 0.3 + j * 0.42, w: 1.8, h: 0, line: { color: \"334155\", width: 1 } });\n  }\n\n  sl.addText(\"KEY TAKEAWAYS  →  2025 OUTLOOK\", { x: 0.5, y: 0.28, w: 9, h: 0.38, fontSize: 11, color: C.accent, bold: true, charSpacing: 3, margin: 0 });\n\n  sl.addText(\"What 2024 Tells Us About JavaScript's Future\", {\n    x: 0.5, y: 0.72, w: 9, h: 0.72,\n    fontSize: 28, fontFace: \"Arial Black\", color: C.white, bold: true, margin: 0\n  });\n\n  sl.addShape(pres.shapes.LINE, { x: 0.5, y: 1.5, w: 9.0, h: 0, line: { color: \"334155\", width: 1 } });\n\n  const takeaways = [\n    { num: \"01\", color: C.barHl,  title: \"Component Ownership Beats Imports\", body: \"shadcn/ui's copy-paste model won for a second year, reaching 77.5k stars. Owning and customizing code beats abstracted library lock-in.\" },\n    { num: \"02\", color: C.sky,    title: \"HTML-First is Serious Architecture\", body: \"htmx overtook React as the #1 front-end framework by stars. Server-driven, low-JS approaches are gaining real traction.\" },\n    { num: \"03\", color: \"A78BFA\", title: \"React Becomes a Framework Spec\", body: \"Server Components and Server Functions in React 19 mean Next.js, Remix, and others each interpret React primitives differently.\" },\n    { num: \"04\", color: \"34D399\", title: \"AI Integration is Table Stakes\", body: \"4 of the top 10 projects (n8n, Flowise, Supabase, AFFiNE) have native AI capabilities. AI is infrastructure now, not a feature.\" },\n    { num: \"05\", color: \"F472B6\", title: \"Vue's Ecosystem Signals Maturity\", body: \"A wave of high-quality UI libraries + Vue 3.5 reactivity rework signal a confident, mature ecosystem on par with React's tooling.\" },\n  ];\n\n  takeaways.forEach((t, i) => {\n    const col = i < 3 ? 0 : 1;\n    const row = i < 3 ? i : i - 3;\n    const tx = col === 0 ? 0.4 : 5.2;\n    const ty = 1.65 + row * 1.12;\n    const bw = 4.55;\n\n    sl.addShape(pres.shapes.RECTANGLE, { x: tx, y: ty, w: bw, h: 0.95, fill: { color: \"1E293B\" }, line: { color: \"334155\", width: 1 } });\n    sl.addShape(pres.shapes.RECTANGLE, { x: tx, y: ty, w: 0.08, h: 0.95, fill: { color: t.color }, line: { color: t.color } });\n\n    sl.addText(t.num, { x: tx + 0.15, y: ty + 0.08, w: 0.45, h: 0.3, fontSize: 11, color: t.color, bold: true, margin: 0 });\n    sl.addText(t.title, { x: tx + 0.6, y: ty + 0.06, w: bw - 0.72, h: 0.3, fontSize: 12, fontFace: \"Arial Black\", color: C.white, bold: true, margin: 0 });\n    sl.addText(t.body, { x: tx + 0.15, y: ty + 0.38, w: bw - 0.25, h: 0.52, fontSize: 9.5, color: \"94A3B8\", margin: 0 });\n  });\n\n  // Footer\n  sl.addText(\"risingstars.js.org/2024  |  Data: GitHub API  |  Curated by Best of JS\", {\n    x: 0.5, y: 5.28, w: 9.0, h: 0.25, fontSize: 9, color: \"475569\", align: \"center\", margin: 0\n  });\n}\n\n// ─────────────────────────────────────────────────────────────\n// Save\n// ─────────────────────────────────────────────────────────────\npres.writeFile({ fileName: \"/app/output/final_deck.pptx\" })\n  .then(() => console.log(\"✅  Saved: /app/output/final_deck.pptx\"))\n  .catch(err => { console.error(\"❌ Error:\", err); process.exit(1); });\n", "numLines": 596, "startLine": 1, "totalLines": 596}}

