const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "2024 JavaScript Rising Stars";

const C = {
  darkBg:    "0F172A",
  darkBg2:   "1E293B",
  accent:    "F59E0B",
  accentDim: "FCD34D",
  sky:       "38BDF8",
  skyDark:   "0284C7",
  white:     "FFFFFF",
  lightBg:   "F8FAFC",
  text:      "1E293B",
  textMuted: "64748B",
  textLight: "CBD5E1",
  border:    "E2E8F0",
  barMain:   "38BDF8",
  barHl:     "F59E0B",
};

const mkShadow = () => ({ type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.10 });

// ─────────────────────────────────────────────────────────────
// SLIDE 1: Title Cover
// ─────────────────────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.darkBg };

  // Left accent bar — wider so it's a clear design element
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.35, h: 5.625,
    fill: { color: C.accent }, line: { color: C.accent }
  });

  // Decorative grid top-right — kept well within slide boundaries
  for (let i = 0; i < 4; i++) {
    sl.addShape(pres.shapes.LINE, { x: 7.0 + i * 0.4, y: 0.4, w: 0, h: 1.1, line: { color: "334155", width: 1 } });
  }
  for (let j = 0; j < 3; j++) {
    sl.addShape(pres.shapes.LINE, { x: 7.0, y: 0.4 + j * 0.38, w: 1.2, h: 0, line: { color: "334155", width: 1 } });
  }

  // Eyebrow
  sl.addText("9TH ANNUAL EDITION  •  BEST OF JS", {
    x: 0.65, y: 1.1, w: 8.8, h: 0.38,
    fontSize: 11, color: C.accent, bold: true, charSpacing: 3, align: "left", margin: 0
  });

  // Main title
  sl.addText("2024 JavaScript\nRising Stars", {
    x: 0.65, y: 1.58, w: 8.8, h: 1.55,
    fontSize: 42, fontFace: "Arial Black", color: C.white, bold: true, align: "left", margin: 0
  });

  // Subtitle
  sl.addText("The Year's Hottest Projects by GitHub Stars", {
    x: 0.65, y: 3.22, w: 8.8, h: 0.45,
    fontSize: 20, color: C.sky, align: "left", margin: 0
  });

  // Divider
  sl.addShape(pres.shapes.LINE, { x: 0.65, y: 3.78, w: 8.7, h: 0, line: { color: "334155", width: 1 } });

  // Methodology note
  sl.addText([
    { text: "Methodology: ", options: { bold: true, color: C.accent } },
    { text: "GitHub stars added Jan 1 – Dec 31, 2024, across projects curated by Best of JS.", options: { color: C.textLight } }
  ], { x: 0.65, y: 3.92, w: 8.7, h: 0.45, fontSize: 12, margin: 0 });

  // Bottom stat pills — with comfortable bottom margin
  const pills = [
    { label: "Projects Tracked", val: "1,000+" },
    { label: "Data Source", val: "GitHub API" },
    { label: "Edition", val: "2024" }
  ];
  pills.forEach((p, i) => {
    const px = 0.65 + i * 2.95;
    sl.addShape(pres.shapes.RECTANGLE, {
      x: px, y: 4.52, w: 2.7, h: 0.8,
      fill: { color: "1E293B" }, line: { color: "334155", width: 1 }
    });
    sl.addText(p.val, { x: px, y: 4.57, w: 2.7, h: 0.35, fontSize: 16, fontFace: "Arial Black", color: C.accent, bold: true, align: "center", margin: 0 });
    sl.addText(p.label, { x: px, y: 4.94, w: 2.7, h: 0.24, fontSize: 10, color: C.textLight, align: "center", margin: 0 });
  });
}

// ─────────────────────────────────────────────────────────────
// SLIDE 2: Overall Top 10
// ─────────────────────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.lightBg };

  sl.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.72, fill: { color: C.darkBg }, line: { color: C.darkBg } });
