  // Horizontal bar chart — narrower to leave room for annotation panel with margin
  const top10 = [
    { name: "Payload",    val: 14.4 },
    { name: "Flowise",    val: 14.5 },
    { name: "Supabase",   val: 14.5 },
    { name: "Tauri",      val: 15.9 },
    { name: "htmx",       val: 16.8 },
    { name: "n8n",        val: 17.0 },
    { name: "Bruno",      val: 18.7 },
    { name: "AFFiNE",     val: 19.6 },
    { name: "Excalidraw", val: 27.0 },
    { name: "shadcn/ui",  val: 38.0 },
