    chartArea: { fill: { color: C.lightBg } },
    catAxisLabelColor: C.text,
    catAxisFontSize: 11,
    valAxisLabelColor: C.textMuted,
    valAxisFontSize: 10,
    valGridLine: { color: C.border, size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelFormatCode: '0.0"k"',
    dataLabelPosition: "outEnd",
    dataLabelColor: C.text,
    dataLabelFontSize: 10,
    showLegend: false,
    valAxisMinVal: 0,
    valAxisMaxVal: 45,
  });

  // Right annotation panel — 0.5" from right edge
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 7.4, y: 1.44, w: 2.1, h: 3.9,
    fill: { color: C.darkBg }, line: { color: C.darkBg }, shadow: mkShadow()
  });
  sl.addText("WINNER", { x: 7.4, y: 1.68, w: 2.1, h: 0.3, fontSize: 9, color: C.accent, bold: true, charSpacing: 3, align: "center", margin: 0 });
  sl.addText("shadcn/ui", { x: 7.4, y: 2.02, w: 2.1, h: 0.4, fontSize: 14, fontFace: "Arial Black", color: C.white, bold: true, align: "center", margin: 0 });
  sl.addText("+38.0k", { x: 7.4, y: 2.44, w: 2.1, h: 0.55, fontSize: 28, fontFace: "Arial Black", color: C.barHl, bold: true, align: "center", margin: 0 });
  sl.addShape(pres.shapes.LINE, { x: 7.6, y: 3.08, w: 1.7, h: 0, line: { color: "334155", width: 1 } });
  sl.addText("2nd Year\nIn A Row", { x: 7.4, y: 3.16, w: 2.1, h: 0.52, fontSize: 12, color: C.textLight, align: "center", margin: 0 });
  sl.addShape(pres.shapes.LINE, { x: 7.6, y: 3.78, w: 1.7, h: 0, line: { color: "334155", width: 1 } });
  sl.addText("Gap to #2:\n+11k stars", { x: 7.4, y: 3.86, w: 2.1, h: 0.5, fontSize: 11, color: C.textLight, align: "center", margin: 0 });

  // Footer — enough space from bottom
  sl.addText("Stars added Jan 1 – Dec 31, 2024  |  Source: risingstars.js.org/2024", {
    x: 0.4, y: 5.33, w: 9.2, h: 0.22, fontSize: 9, color: C.textMuted, margin: 0
  });
}

// ─────────────────────────────────────────────────────────────
// SLIDE 3: shadcn/ui Deep Dive
// ─────────────────────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.lightBg };

  sl.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.72, fill: { color: C.darkBg }, line: { color: C.darkBg } });
  sl.addText("SHADCN/UI  —  DEEP DIVE", { x: 0.4, y: 0, w: 9.2, h: 0.72, fontSize: 12, color: C.accent, bold: true, charSpacing: 3, valign: "middle", margin: 0 });

  sl.addText("Copy-Paste Components Win for the Second Consecutive Year", {
    x: 0.4, y: 0.82, w: 9.2, h: 0.52,
    fontSize: 18, fontFace: "Arial Black", color: C.text, bold: true, margin: 0
  });

  // Left: year-over-year column chart
  sl.addChart(pres.charts.BAR, [{
    name: "Stars Added",
    labels: ["2023", "2024"],
    values: [39.5, 38.0],
  }], {
    x: 0.4, y: 1.44, w: 3.6, h: 2.55,
    barDir: "col",
    chartColors: [C.sky, C.barHl],
    chartArea: { fill: { color: C.lightBg } },
    catAxisLabelColor: C.text,
    catAxisFontSize: 13,
    valAxisLabelColor: C.textMuted,
    valAxisFontSize: 10,
    valGridLine: { color: C.border, size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelFormatCode: '0.0"k"',
    dataLabelPosition: "outEnd",
    dataLabelColor: C.text,
    dataLabelFontSize: 13,
    showLegend: false,
    valAxisMinVal: 0,
    valAxisMaxVal: 45,
    showTitle: true,
    title: "GitHub Stars Added",
    titleColor: C.textMuted,
    titleFontSize: 11,
