    sl.addText(f.desc, { x: 5.42, y: fy + 0.03, w: 4.1, h: 0.44, fontSize: 10, color: C.textMuted, valign: "middle", margin: 0 });
  });

  // Footer note — clear gap from last feature card
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 4.3, y: 5.13, w: 5.3, h: 0.32,
