const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "2024 JavaScript Rising Stars";

const C = {
  darkBg:    "0F172A",
  darkBg2:   "1E293B",
  accent:    "F59E0B",
  accentDim: "FCD34D",
  sky:       "38BDF8",
  skyDark:   "0284C7",
  white:     "FFFFFF",
  lightBg:   "F8FAFC",
  text:      "1E293B",
  textMuted: "64748B",
  textLight: "CBD5E1",
  border:    "E2E8F0",
  barMain:   "38BDF8",
  barHl:     "F59E0B",
};

const mkShadow = () => ({ type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.10 });

// ─────────────────────────────────────────────────────────────
// SLIDE 1: Title Cover
// ─────────────────────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.darkBg };

  // Left accent bar — wider so it's a clear design element
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.35, h: 5.625,
    fill: { color: C.accent }, line: { color: C.accent }
  });

  // Decorative grid top-right — kept well within slide boundaries
  for (let i = 0; i < 4; i++) {
    sl.addShape(pres.shapes.LINE, { x: 7.0 + i * 0.4, y: 0.4, w: 0, h: 1.1, line: { color: "334155", width: 1 } });
  }
  for (let j = 0; j < 3; j++) {
    sl.addShape(pres.shapes.LINE, { x: 7.0, y: 0.4 + j * 0.38, w: 1.2, h: 0, line: { color: "334155", width: 1 } });
  }

  // Eyebrow
  sl.addText("9TH ANNUAL EDITION  •  BEST OF JS", {
    x: 0.65, y: 1.1, w: 8.8, h: 0.38,
    fontSize: 11, color: C.accent, bold: true, charSpacing: 3, align: "left", margin: 0
  });

  // Main title
  sl.addText("2024 JavaScript\nRising Stars", {
    x: 0.65, y: 1.58, w: 8.8, h: 1.55,
    fontSize: 42, fontFace: "Arial Black", color: C.white, bold: true, align: "left", margin: 0
  });

  // Subtitle
  sl.addText("The Year's Hottest Projects by GitHub Stars", {
    x: 0.65, y: 3.22, w: 8.8, h: 0.45,
    fontSize: 20, color: C.sky, align: "left", margin: 0
  });

  // Divider
  sl.addShape(pres.shapes.LINE, { x: 0.65, y: 3.78, w: 8.7, h: 0, line: { color: "334155", width: 1 } });

  // Methodology note
  sl.addText([
    { text: "Methodology: ", options: { bold: true, color: C.accent } },
    { text: "GitHub stars added Jan 1 – Dec 31, 2024, across projects curated by Best of JS.", options: { color: C.textLight } }
  ], { x: 0.65, y: 3.92, w: 8.7, h: 0.45, fontSize: 12, margin: 0 });

  // Bottom stat pills — with comfortable bottom margin
  const pills = [
    { label: "Projects Tracked", val: "1,000+" },
    { label: "Data Source", val: "GitHub API" },
    { label: "Edition", val: "2024" }
  ];
  pills.forEach((p, i) => {
    const px = 0.65 + i * 2.95;
    sl.addShape(pres.shapes.RECTANGLE, {
      x: px, y: 4.52, w: 2.7, h: 0.8,
      fill: { color: "1E293B" }, line: { color: "334155", width: 1 }
    });
    sl.addText(p.val, { x: px, y: 4.57, w: 2.7, h: 0.35, fontSize: 16, fontFace: "Arial Black", color: C.accent, bold: true, align: "center", margin: 0 });
    sl.addText(p.label, { x: px, y: 4.94, w: 2.7, h: 0.24, fontSize: 10, color: C.textLight, align: "center", margin: 0 });
  });
}

// ─────────────────────────────────────────────────────────────
// SLIDE 2: Overall Top 10
// ─────────────────────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.lightBg };

  sl.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.72, fill: { color: C.darkBg }, line: { color: C.darkBg } });
  sl.addText("OVERALL TOP 10  —  2024", { x: 0.4, y: 0, w: 9.2, h: 0.72, fontSize: 12, color: C.accent, bold: true, charSpacing: 3, valign: "middle", margin: 0 });

  sl.addText("shadcn/ui Leads Overall with +38k Stars, Followed by Excalidraw and AFFiNE", {
    x: 0.4, y: 0.82, w: 9.2, h: 0.52,
    fontSize: 18, fontFace: "Arial Black", color: C.text, bold: true, margin: 0
  });

  // Horizontal bar chart — narrower to leave room for annotation panel with margin
  const top10 = [
    { name: "Payload",    val: 14.4 },
    { name: "Flowise",    val: 14.5 },
    { name: "Supabase",   val: 14.5 },
    { name: "Tauri",      val: 15.9 },
    { name: "htmx",       val: 16.8 },
    { name: "n8n",        val: 17.0 },
    { name: "Bruno",      val: 18.7 },
    { name: "AFFiNE",     val: 19.6 },
    { name: "Excalidraw", val: 27.0 },
    { name: "shadcn/ui",  val: 38.0 },
  ];
  const colors = top10.map((_, i) => i === 9 ? C.barHl : C.barMain);

  sl.addChart(pres.charts.BAR, [{
    name: "Stars Added (k)",
    labels: top10.map(d => d.name),
    values: top10.map(d => d.val),
  }], {
    x: 0.4, y: 1.44, w: 6.8, h: 3.9,
    barDir: "bar",
    chartColors: colors,
    chartArea: { fill: { color: C.lightBg } },
    catAxisLabelColor: C.text,
    catAxisFontSize: 11,
    valAxisLabelColor: C.textMuted,
    valAxisFontSize: 10,
    valGridLine: { color: C.border, size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelFormatCode: '0.0"k"',
    dataLabelPosition: "outEnd",
    dataLabelColor: C.text,
    dataLabelFontSize: 10,
    showLegend: false,
    valAxisMinVal: 0,
    valAxisMaxVal: 45,
  });

  // Right annotation panel — 0.5" from right edge
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 7.4, y: 1.44, w: 2.1, h: 3.9,
    fill: { color: C.darkBg }, line: { color: C.darkBg }, shadow: mkShadow()
  });
  sl.addText("WINNER", { x: 7.4, y: 1.68, w: 2.1, h: 0.3, fontSize: 9, color: C.accent, bold: true, charSpacing: 3, align: "center", margin: 0 });
  sl.addText("shadcn/ui", { x: 7.4, y: 2.02, w: 2.1, h: 0.4, fontSize: 14, fontFace: "Arial Black", color: C.white, bold: true, align: "center", margin: 0 });
  sl.addText("+38.0k", { x: 7.4, y: 2.44, w: 2.1, h: 0.55, fontSize: 28, fontFace: "Arial Black", color: C.barHl, bold: true, align: "center", margin: 0 });
  sl.addShape(pres.shapes.LINE, { x: 7.6, y: 3.08, w: 1.7, h: 0, line: { color: "334155", width: 1 } });
  sl.addText("2nd Year\nIn A Row", { x: 7.4, y: 3.16, w: 2.1, h: 0.52, fontSize: 12, color: C.textLight, align: "center", margin: 0 });
  sl.addShape(pres.shapes.LINE, { x: 7.6, y: 3.78, w: 1.7, h: 0, line: { color: "334155", width: 1 } });
  sl.addText("Gap to #2:\n+11k stars", { x: 7.4, y: 3.86, w: 2.1, h: 0.5, fontSize: 11, color: C.textLight, align: "center", margin: 0 });

  // Footer — enough space from bottom
  sl.addText("Stars added Jan 1 – Dec 31, 2024  |  Source: risingstars.js.org/2024", {
    x: 0.4, y: 5.33, w: 9.2, h: 0.22, fontSize: 9, color: C.textMuted, margin: 0
  });
}

// ─────────────────────────────────────────────────────────────
// SLIDE 3: shadcn/ui Deep Dive
// ─────────────────────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.lightBg };

  sl.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.72, fill: { color: C.darkBg }, line: { color: C.darkBg } });
  sl.addText("SHADCN/UI  —  DEEP DIVE", { x: 0.4, y: 0, w: 9.2, h: 0.72, fontSize: 12, color: C.accent, bold: true, charSpacing: 3, valign: "middle", margin: 0 });

  sl.addText("Copy-Paste Components Win for the Second Consecutive Year", {
    x: 0.4, y: 0.82, w: 9.2, h: 0.52,
    fontSize: 18, fontFace: "Arial Black", color: C.text, bold: true, margin: 0
  });

  // Left: year-over-year column chart
  sl.addChart(pres.charts.BAR, [{
    name: "Stars Added",
    labels: ["2023", "2024"],
    values: [39.5, 38.0],
  }], {
    x: 0.4, y: 1.44, w: 3.6, h: 2.55,
    barDir: "col",
    chartColors: [C.sky, C.barHl],
    chartArea: { fill: { color: C.lightBg } },
    catAxisLabelColor: C.text,
    catAxisFontSize: 13,
    valAxisLabelColor: C.textMuted,
    valAxisFontSize: 10,
    valGridLine: { color: C.border, size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelFormatCode: '0.0"k"',
    dataLabelPosition: "outEnd",
    dataLabelColor: C.text,
    dataLabelFontSize: 13,
    showLegend: false,
    valAxisMinVal: 0,
    valAxisMaxVal: 45,
    showTitle: true,
    title: "GitHub Stars Added",
    titleColor: C.textMuted,
    titleFontSize: 11,
  });

  // Total stars callout — inset from left edge
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 4.1, w: 3.6, h: 0.75,
    fill: { color: C.darkBg }, line: { color: C.darkBg }, shadow: mkShadow()
  });
  sl.addText("77.5k total stars  (created Jan 2023)", {
    x: 0.4, y: 4.1, w: 3.6, h: 0.75,
    fontSize: 12, color: C.accentDim, bold: true, align: "center", valign: "middle", margin: 0
  });

  // Right: feature list — stays within right margin
  const features = [
    { title: "Charts",  desc: "Powered by Recharts — plug-and-play chart components" },
    { title: "Themes",  desc: "CSS variable generation for consistent design tokens" },
    { title: "Blocks",  desc: "Layout collections for typical web app patterns" },
    { title: "Sidebar", desc: "New responsive sidebar component" },
    { title: "CLI v2",  desc: "Next.js, Remix, Vite, Laravel, monorepos + registry ecosystem" },
  ];

  sl.addText("Key 2024 Additions", {
    x: 4.3, y: 1.44, w: 5.3, h: 0.36,
    fontSize: 14, color: C.text, bold: true, margin: 0
  });

  features.forEach((f, i) => {
    const fy = 1.88 + i * 0.58;
    sl.addShape(pres.shapes.RECTANGLE, {
      x: 4.3, y: fy, w: 5.3, h: 0.5,
      fill: { color: C.white }, line: { color: C.border, width: 1 }, shadow: mkShadow()
    });
    sl.addShape(pres.shapes.RECTANGLE, {
      x: 4.3, y: fy, w: 0.08, h: 0.5,
      fill: { color: C.sky }, line: { color: C.sky }
    });
    sl.addText(f.title, { x: 4.46, y: fy + 0.03, w: 1.0, h: 0.44, fontSize: 12, bold: true, color: C.skyDark, margin: 0 });
    sl.addText(f.desc, { x: 5.42, y: fy + 0.03, w: 4.1, h: 0.44, fontSize: 10, color: C.textMuted, valign: "middle", margin: 0 });
  });

  // Footer note — clear gap from last feature card
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 4.3, y: 5.13, w: 5.3, h: 0.32,
    fill: { color: "EFF6FF" }, line: { color: "BFDBFE", width: 1 }
  });
  sl.addText("Vercel v0 AI integration + registry ecosystem (Motion-Primitives, Magic UI) fueled further growth", {
    x: 4.3, y: 5.13, w: 5.3, h: 0.32,
    fontSize: 9, color: C.skyDark, valign: "middle", margin: 5
  });
}

// ─────────────────────────────────────────────────────────────
// SLIDE 4: Front-end Frameworks
// ─────────────────────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.lightBg };

  sl.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.72, fill: { color: C.darkBg }, line: { color: C.darkBg } });
  sl.addText("FRONT-END FRAMEWORKS  —  2024 RANKING", { x: 0.4, y: 0, w: 9.2, h: 0.72, fontSize: 12, color: C.accent, bold: true, charSpacing: 3, valign: "middle", margin: 0 });

  sl.addText("htmx Overtakes React as #1 Front-end Framework by Stars Added", {
    x: 0.4, y: 0.82, w: 9.2, h: 0.52,
    fontSize: 18, fontFace: "Arial Black", color: C.text, bold: true, margin: 0
  });

  // Bar chart
  sl.addChart(pres.charts.BAR, [{
    name: "Stars Added (k)",
    labels: ["htmx", "React", "Svelte", "Vue.js", "Angular"],
    values: [16.8, 14.2, 6.1, 5.9, 3.5],
  }], {
    x: 0.4, y: 1.44, w: 5.5, h: 3.75,
    barDir: "col",
    chartColors: [C.barHl, C.barMain, C.barMain, C.barMain, C.barMain],
    chartArea: { fill: { color: C.lightBg } },
    catAxisLabelColor: C.text,
    catAxisFontSize: 12,
    valAxisLabelColor: C.textMuted,
    valAxisFontSize: 10,
    valGridLine: { color: C.border, size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelFormatCode: '0.0"k"',
    dataLabelPosition: "outEnd",
    dataLabelColor: C.text,
    dataLabelFontSize: 11,
    showLegend: false,
    valAxisMinVal: 0,
    valAxisMaxVal: 20,
  });

  // Right narrative cards — 3 cards, each with enough height to avoid overflow, right-margin safe
  const cards = [
    {
      color: C.barHl,
      title: "htmx  #1 ↑  (+16.8k)",
      body: "Extends HTML with hx-* attributes for AJAX/WebSockets without writing JS. Rose from #2 in 2023. Ideal for server-driven, low-JS architectures."
    },
    {
      color: C.sky,
      title: "React 19  #2  (+14.2k)",
      body: "Launched Dec 2024 after 3 years. Adds Server Components, Server Functions, web components, and form actions. Evolving toward a \"framework specification.\""
    },
    {
